// Static-only consumers, never executed; expected runtime results are contractual.
import { iterate, list, Row } from './candidate.api';

const rows: readonly Row[] = [
  { id: 'a', value: 'A' }, { id: 'b', value: 'B' }, { id: 'a', value: 'A' }
];

export function normal(): readonly string[] {
  const ids: string[] = [];
  for (const row of iterate(rows, { limit: 2 })) ids.push(row.id);
  return ids; // Expected ['a', 'b']; no eager materialization inside iterate.
}

export function pauseAndResume(): void {
  const it = iterate(rows);
  const first = it.next(); // Expected { done: false, value: rows[0] }.
  // Arbitrary caller work here; no SDK advancement during this pause.
  const second = it.next(); // Expected rows[1], not rows[0] again.
  if (!first.done && !second.done) {
    const id: string = second.value.id;
    void id;
  }
  // Standard IterableIterator types make return optional; this proposal requires it.
  if (!it.return) throw new Error('Candidate contract requires return');
  it.return(); // Expected { done: true, value: undefined }; drops iterator's borrow.
  it.return(); // Expected same terminal result, idempotent.
  it.next();   // Expected same terminal result, never restarts.
}

export function breakEarly(): void {
  for (const row of iterate(rows)) {
    void row.id;
    break; // Calls iterator.return() via for-of; permanent close.
  }
}

export function manualCleanup(): void {
  const it = iterate(rows);
  try {
    const step = it.next();
    if (!step.done) void step.value.value;
  } finally {
    if (!it.return) throw new Error('Candidate contract requires return');
    it.return(); // Also closes when caller work throws before exhaustion.
  }
}

export function structuralExtras(): void {
  const extended = { id: '', value: '', extra: 'retained on original object' };
  const options = { limit: 1, callerTag: 'ignored' };
  const it = iterate([extended, extended], options);
  it.next(); // Original extended reference, including extra property; no normalization.
  it.return?.();
}

export function boundaries(): void {
  const omitted = iterate(rows);               // All 3, duplicates retained.
  const undefinedLimit = iterate(rows, { limit: undefined }); // All 3.
  const empty = iterate(rows, { limit: 0 });     // First next is done.
  const negativeZero = iterate(rows, { limit: -0 }); // Same as zero.
  const emptyInput = iterate([]);               // First next is done.
  const aboveLength = iterate(rows, { limit: 10 }); // All 3, no padding.
  const veryLarge = iterate(rows, { limit: 1e20 }); // Finite integer: accepted, all 3.
  void [omitted, undefinedLimit, empty, negativeZero, emptyInput, aboveLength, veryLarge];
}

export function failureAtCall(): void {
  for (const limit of [-1, 0.5, NaN, Infinity, -Infinity]) {
    try {
      // No next() here: error must happen at iterate call, even on empty input.
      iterate([], { limit });
      throw new Error('Missing contractual call-time rejection');
    } catch (error: unknown) {
      if (!(error instanceof RangeError)) throw error;
      // Stable category is RangeError; legacy message 'limit' identifies the field.
      // Correct limit (or omit it) and call iterate again; no input effects to undo.
    }
  }
}

export function independentCalls(): void {
  const a = iterate(rows, { limit: 1 });
  const b = iterate(rows, { limit: 1 });
  a.next(); // rows[0]
  b.next(); // Also rows[0]; a has no effect on b.
  a.return?.();
  b.next(); // done; limit was 1, not affected by a.return().
}

export function compatibility(): void {
  const old: readonly Row[] = list(rows); // Existing default 100 remains.
  const chosen: readonly Row[] = list(rows, { limit: 0 }); // Existing empty result.
  const lazy = iterate(rows, { limit: 100 }); // Explicitly preserves old selection bound.
  // iterate(rows) is NOT a mechanically equivalent default replacement for list(rows).
  void [old, chosen, lazy];
}

