export interface Row { readonly id: string; readonly value: string }

/** Existing contract: omitted limit is 100; invalid limit throws RangeError('limit') now. */
export declare function list(rows: readonly Row[], options?: { readonly limit?: number }): readonly Row[];

/**
 * Proposed synchronous lazy borrowed iteration in input order.
 * Omitted/undefined limit means all; 0 means empty. Validate finite,
 * integer, nonnegative limits at this call, before returning any iterator.
 * Throws RangeError('limit'); no input mutation, whole-input copy or shared state.
 * Borrow remains active until exhaustion or return(); see CONTRACT.md §K3–K5.
 * Runtime return() is required by the contract, despite its optional TS declaration.
 */
export declare function iterate(rows: readonly Row[], options?: { readonly limit?: number }): IterableIterator<Row>;

